import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.C3fpVp7C.js";const p=JSON.parse('{"title":"2. Hash-chained audit log in SQLite","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0002-hash-chained-audit-log.md","filePath":"adr/0002-hash-chained-audit-log.md","lastUpdated":1792160181000}'),n={name:"adr/0002-hash-chained-audit-log.md"};function s(d,e,r,h,c,l){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="_2-hash-chained-audit-log-in-sqlite" tabindex="-1">2. Hash-chained audit log in SQLite <a class="header-anchor" href="#_2-hash-chained-audit-log-in-sqlite" aria-label="Permalink to &quot;2. Hash-chained audit log in SQLite&quot;">​</a></h1><p>Status: accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The audit log is how a principal learns what an agent did under their authority. Anyone with write access to the database could alter it, and a plain table gives no way to notice.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Every grant, attenuation, denied attenuation, revocation, check and approval decision appends a row to the <code>audit</code> table in the same transaction as the change it records. Each row stores <code>hash = sha256(prevHash + &quot;\\n&quot; + canonicalJson({seq, ts, type, actor, data}))</code>. SQLite triggers reject <code>UPDATE</code> and <code>DELETE</code> on the table. <code>agent-auth audit verify</code> recomputes the chain from the API or straight from a database file and reports the first entry that fails. <code>--head</code> checks that a previously anchored head hash is still in the chain.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Edits and deletions in the middle of the log are detected without any extra infrastructure.</li><li>The log is tamper-evident, not tamper-proof. Detecting a rewrite of the whole chain or removed trailing entries needs a head hash stored outside the service.</li><li>Entries are hashed, not signed. Signed checkpoints are on the roadmap.</li><li>Canonical JSON keeps the hash stable across runtimes and key orders.</li></ul>',8)])])}const g=a(n,[["render",s]]);export{p as __pageData,g as default};
